import unittest
from unittest.mock import Mock
from loan import borrow_book

class LoanTests(unittest.TestCase):
    def test_valid_member_preserves_receipt(self):
        member = {"member_id": "patron-803", "name": "Sam Reed"}
        writer = Mock(return_value="loan-215")
        self.assertEqual(borrow_book(member, writer), {"status": "borrowed", "receipt_id": "loan-215"})
        writer.assert_called_once_with(member)

